// Generated by tests/make-native.py from common/common.cpp of the native
// tree; the body between the markers is native text.
#include "native-strip-staged.h"

#include <cctype>
#include <cstring>

std::string native_strip_staged(const std::string & str) {
    size_t start = 0;
    size_t end = str.size();
    while (start < end && std::isspace(str[start])) {
        start++;
    }
    while (end > start && std::isspace(str[end - 1])) {
        end--;
    }
    return str.substr(start, end - start);
}
